import type { Persona } from '@wener/ai/agent/persona';
import type { Skill } from '@wener/ai/agent/skill';
import type { McpServerConfig } from '@wener/ai/mcp';
import type { Endpoint, Model, Provider, Service } from '@wener/ai/schema';
import type { ComponentPropsWithRef, ReactNode } from 'react';

export type AgentConfigResourceKind = 'provider' | 'endpoint' | 'model' | 'service' | 'mcp' | 'persona' | 'skill';
export type AgentConfigStudioSelection = { kind: AgentConfigResourceKind; id?: string };
export type AgentConfigStudioMessages = {
	title: string;
	description: string;
	resourceList: string;
	resourceTypes: string;
	emptyList: string;
	emptySelection: string;
	create: string;
	remove: string;
	identityConflict: (id: string) => string;
	kinds: Record<AgentConfigResourceKind, string>;
};
export type AgentConfigStudioProps = Omit<ComponentPropsWithRef<'section'>, 'onChange' | 'title'> & {
	providers: readonly Provider[];
	endpoints: readonly Endpoint[];
	models: readonly Model[];
	services: readonly Service[];
	mcpServers: readonly McpServerConfig[];
	personas: readonly Persona[];
	skills: readonly Skill[];
	onProvidersChange: (value: Provider[]) => void;
	onEndpointsChange: (value: Endpoint[]) => void;
	onModelsChange: (value: Model[]) => void;
	onServicesChange: (value: Service[]) => void;
	onMcpServersChange: (value: McpServerConfig[]) => void;
	onPersonasChange: (value: Persona[]) => void;
	onSkillsChange: (value: Skill[]) => void;
	selection: AgentConfigStudioSelection;
	onSelectionChange: (value: AgentConfigStudioSelection) => void;
	onCreate?: (kind: AgentConfigResourceKind) => void;
	onRemove?: (selection: AgentConfigStudioSelection) => void;
	disabled?: boolean;
	readOnly?: boolean;
	messages?: Partial<Omit<AgentConfigStudioMessages, 'kinds'>> & {
		kinds?: Partial<AgentConfigStudioMessages['kinds']>;
	};
	empty?: ReactNode;
};

'use client';

import { type Persona, PersonaSchema } from '@wener/ai/agent/persona';
import { getSkillIdentity, type Skill, SkillSchema } from '@wener/ai/agent/skill';
import { type McpServerConfig, McpServerConfigSchema } from '@wener/ai/mcp';
import {
	type Endpoint,
	EndpointSchema,
	type Model,
	ModelSchema,
	type Provider,
	ProviderSchema,
	type Service,
	ServiceSchema,
} from '@wener/ai/schema';
import type { ReactNode } from 'react';
import type { AiConfigSchema } from '../../ui/ai-config-editor';
import { AgentPersonaEditor } from '../agent-persona-editor';
import { AgentSkillEditor } from '../agent-skill-editor';
import { AiEndpointEditor } from '../ai-endpoint-editor';
import { AiModelEditor } from '../ai-model-editor';
import { AiProviderEditor } from '../ai-provider-editor';
import { AiServiceEditor } from '../ai-service-editor';
import { McpServerEditor } from '../mcp-server-editor';
import type {
	AgentConfigResourceKind,
	AgentConfigStudioMessages,
	AgentConfigStudioProps,
	AgentConfigStudioSelection,
} from './agent-config-studio-types';

export type ResourceCollections = Pick<
	AgentConfigStudioProps,
	'providers' | 'endpoints' | 'models' | 'services' | 'mcpServers' | 'personas' | 'skills'
>;
type StudioEditorContext = ResourceCollections &
	Pick<
		AgentConfigStudioProps,
		| 'onProvidersChange'
		| 'onEndpointsChange'
		| 'onModelsChange'
		| 'onServicesChange'
		| 'onMcpServersChange'
		| 'onPersonasChange'
		| 'onSkillsChange'
		| 'onSelectionChange'
		| 'disabled'
		| 'readOnly'
	> & { selection: AgentConfigStudioSelection };
export type StudioResourceItem = { id: string; label: string };

export function resourcesForKind(kind: AgentConfigResourceKind, values: ResourceCollections): StudioResourceItem[] {
	switch (kind) {
		case 'provider':
			return values.providers.map((item) => ({ id: item.id, label: item.title || item.name }));
		case 'endpoint':
			return values.endpoints.map((item) => ({ id: item.id, label: item.title || item.name }));
		case 'model':
			return values.models.map((item) => ({ id: item.id, label: item.title || item.name }));
		case 'service':
			return values.services.map((item) => ({ id: item.id, label: item.title || item.name }));
		case 'mcp':
			return values.mcpServers.map((item, index) => ({
				id: mcpIdentity(item, index),
				label: item.title || item.name || item.id || `MCP Server ${index + 1}`,
			}));
		case 'persona':
			return values.personas.map((item) => ({ id: item.id, label: item.title || item.name }));
		case 'skill':
			return values.skills.map((item) => ({ id: skillIdentity(item), label: item.name }));
	}
}

export function renderSelectedStudioEditor(
	context: StudioEditorContext,
	messages: AgentConfigStudioMessages,
): ReactNode {
	const { selection, disabled, readOnly } = context;
	const providerOptions = context.providers.map((entry) => ({ value: entry.id, label: entry.title || entry.name }));
	switch (selection.kind) {
		case 'provider': {
			const item = context.providers.find((entry) => entry.id === selection.id);
			return item ? (
				<AiProviderEditor
					value={item}
					schema={uniqueIdentitySchema(ProviderSchema, context.providers, item, providerIdentity, 'id', messages)}
					disabled={disabled}
					readOnly={readOnly}
					onChange={(next) =>
						updateStudioResource(
							context.providers,
							item,
							next,
							'provider',
							next.id,
							context.onProvidersChange,
							context.onSelectionChange,
						)
					}
				/>
			) : null;
		}
		case 'endpoint': {
			const item = context.endpoints.find((entry) => entry.id === selection.id);
			return item ? (
				<AiEndpointEditor
					value={item}
					schema={uniqueIdentitySchema(EndpointSchema, context.endpoints, item, endpointIdentity, 'id', messages)}
					providerOptions={providerOptions}
					disabled={disabled}
					readOnly={readOnly}
					onChange={(next) =>
						updateStudioResource(
							context.endpoints,
							item,
							next,
							'endpoint',
							next.id,
							context.onEndpointsChange,
							context.onSelectionChange,
						)
					}
				/>
			) : null;
		}
		case 'model': {
			const item = context.models.find((entry) => entry.id === selection.id);
			return item ? (
				<AiModelEditor
					value={item}
					schema={uniqueIdentitySchema(ModelSchema, context.models, item, modelIdentity, 'id', messages)}
					providerOptions={providerOptions}
					endpointOptions={endpointOptionsForProvider(context.endpoints, item.providerId)}
					disabled={disabled}
					readOnly={readOnly}
					onChange={(next) =>
						updateStudioResource(
							context.models,
							item,
							next,
							'model',
							next.id,
							context.onModelsChange,
							context.onSelectionChange,
						)
					}
				/>
			) : null;
		}
		case 'service': {
			const item = context.services.find((entry) => entry.id === selection.id);
			return item ? (
				<AiServiceEditor
					value={item}
					schema={uniqueIdentitySchema(ServiceSchema, context.services, item, serviceIdentity, 'id', messages)}
					providerOptions={providerOptions}
					endpointOptions={endpointOptionsForProvider(context.endpoints, item.providerId)}
					disabled={disabled}
					readOnly={readOnly}
					onChange={(next) =>
						updateStudioResource(
							context.services,
							item,
							next,
							'service',
							next.id,
							context.onServicesChange,
							context.onSelectionChange,
						)
					}
				/>
			) : null;
		}
		case 'mcp': {
			const index = context.mcpServers.findIndex((entry, itemIndex) => mcpIdentity(entry, itemIndex) === selection.id);
			const item = context.mcpServers[index];
			return item ? (
				<McpServerEditor
					value={item}
					schema={uniqueIdentitySchema(
						McpServerConfigSchema,
						context.mcpServers,
						item,
						(entry) => mcpIdentity(entry, context.mcpServers.indexOf(entry)),
						'id',
						messages,
					)}
					disabled={disabled}
					readOnly={readOnly}
					onChange={(next) =>
						updateStudioResource(
							context.mcpServers,
							item,
							next,
							'mcp',
							next.id || next.name || `mcp-${index + 1}`,
							context.onMcpServersChange,
							context.onSelectionChange,
						)
					}
				/>
			) : null;
		}
		case 'persona': {
			const item = context.personas.find((entry) => entry.id === selection.id);
			return item ? (
				<AgentPersonaEditor
					value={item}
					schema={uniqueIdentitySchema(PersonaSchema, context.personas, item, personaIdentity, 'id', messages)}
					disabled={disabled}
					readOnly={readOnly}
					onChange={(next) =>
						updateStudioResource(
							context.personas,
							item,
							next,
							'persona',
							next.id,
							context.onPersonasChange,
							context.onSelectionChange,
						)
					}
				/>
			) : null;
		}
		case 'skill': {
			const item = context.skills.find((entry) => skillIdentity(entry) === selection.id);
			return item ? (
				<AgentSkillEditor
					value={item}
					schema={uniqueIdentitySchema(SkillSchema, context.skills, item, skillIdentity, 'id', messages)}
					disabled={disabled}
					readOnly={readOnly}
					onChange={(next) =>
						updateStudioResource(
							context.skills,
							item,
							next,
							'skill',
							skillIdentity(next),
							context.onSkillsChange,
							context.onSelectionChange,
						)
					}
				/>
			) : null;
		}
	}
}

function uniqueIdentitySchema<T>(
	base: AiConfigSchema<T>,
	items: readonly T[],
	current: T,
	identity: (value: T) => string,
	field: string,
	messages: AgentConfigStudioMessages,
): AiConfigSchema<T> {
	return {
		safeParse(value) {
			const parsed = base.safeParse(value);
			if (!parsed.success) return parsed;
			const nextId = identity(parsed.data);
			if (items.some((item) => item !== current && identity(item) === nextId)) {
				return {
					success: false,
					error: { issues: [{ path: [field], message: messages.identityConflict(nextId) }] },
				};
			}
			return parsed;
		},
	};
}

function updateStudioResource<T>(
	items: readonly T[],
	current: T,
	next: T,
	kind: AgentConfigResourceKind,
	nextId: string,
	onChange: (items: T[]) => void,
	onSelectionChange: (selection: AgentConfigStudioSelection) => void,
): void {
	onChange(items.map((item) => (item === current ? next : item)));
	onSelectionChange({ kind, id: nextId });
}

export function endpointOptionsForProvider(endpoints: readonly Endpoint[], providerId?: string) {
	return endpoints
		.filter((endpoint) => !providerId || !endpoint.providerId || endpoint.providerId === providerId)
		.map((endpoint) => ({
			value: endpoint.id,
			label: endpointOptionLabel(endpoint),
		}));
}

function endpointOptionLabel(endpoint: Endpoint): string {
	const label = endpoint.title || endpoint.name;
	return label === endpoint.id ? endpoint.id : `${label} · ${endpoint.id}`;
}

function providerIdentity(value: Provider): string {
	return value.id;
}
function endpointIdentity(value: Endpoint): string {
	return value.id;
}
function modelIdentity(value: Model): string {
	return value.id;
}
function serviceIdentity(value: Service): string {
	return value.id;
}
function personaIdentity(value: Persona): string {
	return value.id;
}
function skillIdentity(value: Skill): string {
	return getSkillIdentity(value);
}
function mcpIdentity(value: McpServerConfig, index: number): string {
	return value.id || value.name || `mcp-${index + 1}`;
}

'use client';

import { Bot, Box, BrainCircuit, Cable, Network, Plus, ServerCog, Sparkles, Trash2 } from 'lucide-react';
import type { ComponentType, KeyboardEvent } from 'react';
import { useId, useRef } from 'react';
import { type ResourceCollections, renderSelectedStudioEditor, resourcesForKind } from './agent-config-studio-editor';
import type {
	AgentConfigResourceKind,
	AgentConfigStudioMessages,
	AgentConfigStudioProps,
} from './agent-config-studio-types';

const defaultMessages: AgentConfigStudioMessages = {
	title: 'Agent 配置工作室',
	description: '集中浏览独立资源，并使用 canonical editor 修改当前选择。',
	resourceList: '资源列表',
	resourceTypes: '配置资源类型',
	emptyList: '此分类暂无资源',
	emptySelection: '请选择一个资源开始编辑',
	create: '新建资源',
	remove: '删除资源',
	identityConflict: (id) => `资源 ID“${id}”已存在，请使用不同的 ID。`,
	kinds: {
		provider: 'AI 提供方',
		endpoint: 'AI Endpoint',
		model: 'AI 模型',
		service: 'AI 服务',
		mcp: 'MCP 服务',
		persona: '角色',
		skill: '技能',
	},
};

const kinds: readonly {
	kind: AgentConfigResourceKind;
	icon: ComponentType<{ className?: string; 'aria-hidden'?: 'true' }>;
}[] = [
	{ kind: 'provider', icon: Cable },
	{ kind: 'endpoint', icon: Network },
	{ kind: 'model', icon: BrainCircuit },
	{ kind: 'service', icon: ServerCog },
	{ kind: 'mcp', icon: Box },
	{ kind: 'persona', icon: Bot },
	{ kind: 'skill', icon: Sparkles },
];

export function AgentConfigStudio({
	providers,
	endpoints,
	models,
	services,
	mcpServers,
	personas,
	skills,
	onProvidersChange,
	onEndpointsChange,
	onModelsChange,
	onServicesChange,
	onMcpServersChange,
	onPersonasChange,
	onSkillsChange,
	selection,
	onSelectionChange,
	onCreate,
	onRemove,
	disabled = false,
	readOnly = false,
	messages: overrides,
	empty,
	className,
	...props
}: AgentConfigStudioProps) {
	const messages: AgentConfigStudioMessages = {
		...defaultMessages,
		...overrides,
		kinds: { ...defaultMessages.kinds, ...overrides?.kinds },
	};
	const id = useId();
	const tabRefs = useRef<Partial<Record<AgentConfigResourceKind, HTMLButtonElement | null>>>({});
	const collections = { providers, endpoints, models, services, mcpServers, personas, skills };
	const counts = {
		provider: providers.length,
		endpoint: endpoints.length,
		model: models.length,
		service: services.length,
		mcp: mcpServers.length,
		persona: personas.length,
		skill: skills.length,
	};
	const selectKind = (kind: AgentConfigResourceKind) => {
		const first = resourcesForKind(kind, collections)[0];
		onSelectionChange({ kind, id: first?.id });
	};
	const moveTabFocus = (event: KeyboardEvent<HTMLButtonElement>, currentIndex: number) => {
		let nextIndex: number | undefined;
		if (event.key === 'ArrowRight') nextIndex = (currentIndex + 1) % kinds.length;
		else if (event.key === 'ArrowLeft') nextIndex = (currentIndex - 1 + kinds.length) % kinds.length;
		else if (event.key === 'Home') nextIndex = 0;
		else if (event.key === 'End') nextIndex = kinds.length - 1;
		if (nextIndex === undefined) return;
		event.preventDefault();
		const nextKind = kinds[nextIndex]!.kind;
		selectKind(nextKind);
		tabRefs.current[nextKind]?.focus();
	};
	return (
		<section data-slot='agent-config-studio' className={`bg-base-100 min-w-0 ${className ?? ''}`} {...props}>
			<header className='border-base-300 border-b px-3 py-4 md:px-5'>
				<h1 className='text-base font-semibold'>{messages.title}</h1>
				<p className='text-base-content/60 mt-0.5 text-sm'>{messages.description}</p>
			</header>
			<div
				className='border-base-300 flex min-w-0 gap-1 overflow-x-auto border-b px-2 py-2'
				role='tablist'
				aria-label={messages.resourceTypes}
			>
				{kinds.map(({ kind, icon: Icon }, index) => (
					<button
						ref={(element) => {
							tabRefs.current[kind] = element;
						}}
						key={kind}
						id={`${id}-tab-${kind}`}
						type='button'
						role='tab'
						aria-controls={`${id}-panel-${kind}`}
						aria-selected={selection.kind === kind}
						tabIndex={selection.kind === kind ? 0 : -1}
						className={`btn btn-sm shrink-0 ${selection.kind === kind ? 'btn-active' : 'btn-ghost'}`}
						onClick={() => selectKind(kind)}
						onKeyDown={(event) => moveTabFocus(event, index)}
					>
						<Icon aria-hidden='true' className='size-4' />
						<span>{messages.kinds[kind]}</span>
						<span className='badge badge-sm'>{counts[kind]}</span>
					</button>
				))}
			</div>
			{kinds.map(({ kind }) => (
				<div
					key={kind}
					id={`${id}-panel-${kind}`}
					role='tabpanel'
					aria-labelledby={`${id}-tab-${kind}`}
					hidden={selection.kind !== kind}
				>
					{selection.kind === kind ? (
						<StudioKindPanel
							kind={kind}
							collections={collections}
							messages={messages}
							selectionId={selection.id}
							disabled={disabled}
							readOnly={readOnly}
							onCreate={onCreate}
							onRemove={onRemove}
							empty={empty}
							editorProps={{
								onProvidersChange,
								onEndpointsChange,
								onModelsChange,
								onServicesChange,
								onMcpServersChange,
								onPersonasChange,
								onSkillsChange,
								onSelectionChange,
							}}
						/>
					) : null}
				</div>
			))}
		</section>
	);
}

type StudioKindPanelProps = {
	kind: AgentConfigResourceKind;
	collections: ResourceCollections;
	messages: AgentConfigStudioMessages;
	selectionId?: string;
	disabled: boolean;
	readOnly: boolean;
	onCreate?: AgentConfigStudioProps['onCreate'];
	onRemove?: AgentConfigStudioProps['onRemove'];
	empty?: AgentConfigStudioProps['empty'];
	editorProps: Pick<
		AgentConfigStudioProps,
		| 'onProvidersChange'
		| 'onEndpointsChange'
		| 'onModelsChange'
		| 'onServicesChange'
		| 'onMcpServersChange'
		| 'onPersonasChange'
		| 'onSkillsChange'
		| 'onSelectionChange'
	>;
};

function StudioKindPanel({
	kind,
	collections,
	messages,
	selectionId,
	disabled,
	readOnly,
	onCreate,
	onRemove,
	empty,
	editorProps,
}: StudioKindPanelProps) {
	const resources = resourcesForKind(kind, collections);
	const selected = resources.find((resource) => resource.id === selectionId);
	const selection = { kind, id: selectionId };
	return (
		<div className='grid min-w-0 md:min-h-[42rem] md:grid-cols-[16rem_minmax(0,1fr)]'>
			<aside className='border-base-300 min-w-0 border-b md:border-e md:border-b-0' aria-label={messages.resourceList}>
				<div className='border-base-300 flex min-h-12 items-center justify-between gap-2 border-b px-3'>
					<h2 className='text-sm font-semibold'>{messages.kinds[kind]}</h2>
					{onCreate && !readOnly ? (
						<button
							type='button'
							className='btn btn-ghost btn-sm btn-square'
							title={messages.create}
							aria-label={messages.create}
							disabled={disabled}
							onClick={() => onCreate(kind)}
						>
							<Plus aria-hidden='true' className='size-4' />
						</button>
					) : null}
				</div>
				<nav className='max-h-56 overflow-auto p-2 md:max-h-[calc(100vh-16rem)]'>
					{resources.length ? (
						resources.map((resource) => (
							<button
								key={resource.id}
								type='button'
								className={`mb-1 flex min-h-11 w-full min-w-0 items-center rounded-sm px-2 text-left ${selectionId === resource.id ? 'bg-primary text-primary-content' : 'hover:bg-base-200'}`}
								aria-current={selectionId === resource.id ? 'page' : undefined}
								onClick={() => editorProps.onSelectionChange({ kind, id: resource.id })}
							>
								<span className='min-w-0 flex-1'>
									<span className='block truncate text-sm font-medium'>{resource.label}</span>
									<span className='text-base-content/55 block truncate text-xs'>{resource.id}</span>
								</span>
							</button>
						))
					) : (
						<div className='text-base-content/55 px-2 py-8 text-center text-sm'>{messages.emptyList}</div>
					)}
				</nav>
			</aside>
			<main className='min-w-0 p-2 sm:p-4'>
				{selected ? (
					<div className='min-w-0'>
						{onRemove && !readOnly ? (
							<div className='mb-2 flex justify-end'>
								<button
									type='button'
									className='btn btn-ghost btn-sm text-error'
									disabled={disabled}
									onClick={() => onRemove(selection)}
								>
									<Trash2 aria-hidden='true' className='size-4' />
									{messages.remove}
								</button>
							</div>
						) : null}
						{renderSelectedStudioEditor({ ...collections, ...editorProps, selection, disabled, readOnly }, messages)}
					</div>
				) : (
					(empty ?? (
						<div className='grid min-h-72 place-items-center text-center'>
							<div>
								<BrainCircuit aria-hidden='true' className='text-base-content/30 mx-auto size-10' />
								<p className='text-base-content/60 mt-3 text-sm'>{messages.emptySelection}</p>
							</div>
						</div>
					))
				)}
			</main>
		</div>
	);
}
